import pytest

from minimum_spanning_tree import minimum_spanning_tree


def _total_weight(edges, weight_by_edge):
    """Helper: sum weights of edges using the input dict."""
    return sum(weight_by_edge[e] for e in edges)


def _vertices(weight_by_edge):
    """Helper: collect all vertices from edge keys."""
    verts = set()
    for (u, v) in weight_by_edge:
        verts.add(u)
        verts.add(v)
    return verts


def _is_connected(edges, vertices):
    """Helper: check whether the given edge set connects all vertices."""
    if not vertices:
        return True
    adj = {v: set() for v in vertices}
    for (u, v) in edges:
        adj[u].add(v)
        adj[v].add(u)
    start = next(iter(vertices))
    seen = {start}
    stack = [start]
    while stack:
        node = stack.pop()
        for nb in adj[node]:
            if nb not in seen:
                seen.add(nb)
                stack.append(nb)
    return seen == vertices


