def _is_valid_rpn(tokens):
    """Check whether a token list is a valid RPN expression.

    Uses a stack simulation: integers push, operators pop two.
    """
    stack = 0
    for token in tokens:
        if isinstance(token, int):
            stack += 1
        else:
            if stack < 2:
                return False
            stack -= 1
    return stack == 1


